import { useState } from "react";
import CompanyLayout from "./CompanyLayout";
import ax from "../api";
// ── البيانات الأولية ──
const OFFERS = [
  { id: 1, title: "Full-Stack Web Developer" },
  { id: 2, title: "Data Analyst" },
  { id: 3, title: "DevOps Intern" },
];

const INIT_CANDIDATES = [
  { id: 1, offerId: 1, name: "Amira Benali", university: "IFA", level: "L3", wilaya: "Alger", skills: ["React", "Node.js", "PostgreSQL"], github: "github.com/amira-benali", appliedDate: "Apr 24", status: "pending", hasCV: true, note: "" },
  { id: 2, offerId: 1, name: "Karim Hadj", university: "USTHB", level: "M1", wilaya: "Alger", skills: ["Vue", "Laravel", "MySQL"], github: "github.com/karim-hadj", appliedDate: "Apr 23", status: "pending", hasCV: true, note: "" },
  { id: 3, offerId: 1, name: "Lina Zouaoui", university: "UMBB", level: "L3", wilaya: "Boumerdès", skills: ["React", "TypeScript", "Git"], github: "", appliedDate: "Apr 22", status: "accepted", hasCV: false, note: "Great React skills." },
  { id: 4, offerId: 2, name: "Sara Maamri", university: "IFA", level: "M1", wilaya: "Alger", skills: ["Python", "SQL", "Power BI"], github: "github.com/sara-m", appliedDate: "Apr 22", status: "accepted", hasCV: true, note: "Perfect profile." },
  { id: 5, offerId: 2, name: "Yacine Bouzid", university: "ESI", level: "L3", wilaya: "Alger", skills: ["Python", "R", "Tableau"], github: "github.com/yacine-b", appliedDate: "Apr 20", status: "rejected", hasCV: true, note: "Looking for more experience." },
  { id: 6, offerId: 3, name: "Amine Ferhat", university: "USTHB", level: "M2", wilaya: "Alger", skills: ["Docker", "Kubernetes", "Linux"], github: "github.com/amine-f", appliedDate: "Apr 18", status: "pending", hasCV: true, note: "" },
];

const STATUS_CFG = {
  pending: { badge: "badge-orange", label: "Pending", icon: "⏳" },
  accepted: { badge: "badge-green", label: "Accepted", icon: "✅" },
  rejected: { badge: "badge-red", label: "Rejected", icon: "❌" },
};

// ── نافذة اتخاذ القرار (Decision Modal) ──
function DecisionModal({ candidate, onClose, onDecide }) {
  const [note, setNote] = useState(candidate.note || "");
  const [action, setAction] = useState(null); 
  const [done, setDone] = useState(false);

  const confirm = () => {
    onDecide(candidate.id, action, note);
    setDone(true);
  };

  if (done) return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-box text-center" onClick={e => e.stopPropagation()}>
        <div className="text-5xl mb-3">{action === "accepted" ? "🎉" : "📭"}</div>
        <h3 className="font-syne font-bold text-slate-900 text-xl mb-2">
          {action === "accepted" ? "Application accepted!" : "Application rejected"}
        </h3>
        <p className="text-sm text-slate-500 font-light mb-6">
          {action === "accepted"
            ? <><strong className="text-slate-700">{candidate.name}</strong> will be notified.</>
            : <><strong className="text-slate-700">{candidate.name}</strong> has been notified.</>
          }
        </p>
        <button onClick={onClose} className="shimmer-btn text-white font-semibold px-8 py-2.5 rounded-xl text-sm">Done</button>
      </div>
    </div>
  );

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-box" onClick={e => e.stopPropagation()}>
        <div className="flex items-center gap-4 mb-5 pb-5 border-b border-slate-100">
          <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-blue-400 to-blue-700 flex items-center justify-center text-xl font-bold text-white shrink-0">
            {candidate.name.split(" ").map(n => n[0]).join("")}
          </div>
          <div>
            <h3 className="font-syne font-extrabold text-slate-900 text-xl">{candidate.name}</h3>
            <p className="text-sm text-slate-500">{candidate.level} · {candidate.university}</p>
            </div>
        </div>
        <div className="mb-5">
          <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Decision note</label>
          <textarea rows={2} value={note} onChange={e => setNote(e.target.value)}
            placeholder="Reason for this decision..." className="input-field resize-none" />
        </div>

        {!action ? (
          <div className="grid grid-cols-2 gap-3">
            <button onClick={() => setAction("rejected")} className="reject-btn text-white font-semibold py-3 rounded-xl text-sm">✕ Reject</button>
            <button onClick={() => setAction("accepted")} className="accept-btn text-white font-semibold py-3 rounded-xl text-sm">✓ Accept</button>
          </div>
        ) : (
          <div className="space-y-3">
            <div className={`p-3 rounded-xl text-sm font-medium ${action === "accepted" ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-red-50 text-red-700 border-red-200"} border`}>
              Confirm {action === "accepted" ? "accepting" : "rejecting"} <strong>{candidate.name}</strong>?
            </div>
            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => setAction(null)} className="py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50">Back</button>
              <button onClick={confirm} className={`${action === "accepted" ? "accept-btn" : "reject-btn"} text-white font-semibold py-2.5 rounded-xl text-sm`}>Confirm</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default function CompanyCandidates() {
  const [candidates, setCandidates] = useState(INIT_CANDIDATES);
  const [selectedOffer, setSelectedOffer] = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState(null);
  const [modal, setModal] = useState(null);

  const handleDecide = (id, status, note) => {
    setCandidates(prev => prev.map(c => c.id === id ? { ...c, status, note } : c));
    if (selected?.id === id) setSelected(prev => ({ ...prev, status, note }));
  };

  const filtered = candidates.filter(c => {
    const matchOffer = selectedOffer === "all" || c.offerId === Number(selectedOffer);
    const matchStatus = filterStatus === "all" || c.status === filterStatus;
    const matchSearch = !search || 
                       c.name.toLowerCase().includes(search.toLowerCase()) || 
                       c.skills.some(s => s.toLowerCase().includes(search.toLowerCase()));
    return matchOffer && matchStatus && matchSearch;
  });

  const pendingCount = candidates.filter(c => c.status === "pending").length;

  return (
    <CompanyLayout active="candidates" pendingCount={pendingCount}>
      <div className="p-5 md:p-8">
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-blue-500 uppercase tracking-widest mb-1">Candidates</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Candidate tracking</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">{candidates.length} total · <span className="text-amber-600 font-medium">{pendingCount} pending review</span></p>
        </div>

        {/* Filters */}
        <div className="anim-fade-up anim-d1 card border border-slate-200 p-4 mb-5">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="relative flex-1">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">🔍</span>
              <input type="text" placeholder="Search by name or skill..." value={search} onChange={e => setSearch(e.target.value)} className="input-field pl-9" />
              </div>
            
            <select value={selectedOffer} onChange={e => setSelectedOffer(e.target.value)} className="input-field md:w-52">
                <option value="all">All offers</option>
                {OFFERS.map(o => <option key={o.id} value={o.id}>{o.title}</option>)}
            </select>
          
            <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="input-field md:w-36">
              <option value="all">All statuses</option>
              <option value="pending">Pending</option>
              <option value="accepted">Accepted</option>
              <option value="rejected">Rejected</option>
            </select>
          </div>
        </div>

        <div className="grid md:grid-cols-5 gap-5">
          <div className="md:col-span-2 space-y-2">
            {filtered.map(c => (
              <div key={c.id} onClick={() => setSelected(c)} className={`card border candidate-row p-4 ${selected?.id === c.id ? "selected border-blue-300 shadow-sm" : "border-slate-200"}`}>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-400 to-blue-600 flex items-center justify-center text-sm font-bold text-white shrink-0">
                    {c.name.split(" ").map(n => n[0]).join("")}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-semibold text-sm text-slate-800 truncate">{c.name}</div>
                    <div className="text-xs text-slate-400 truncate">{c.university}</div>
                  </div>
                  <span className={`badge ${STATUS_CFG[c.status].badge}`}>{STATUS_CFG[c.status].label}</span>
                </div>
              </div>
            ))}
          </div>

          <div className="md:col-span-3">
            {selected ? (
              <div className="card border border-slate-200 p-5 sticky top-4">
                <div className="flex items-center gap-4 mb-5 pb-5 border-b border-slate-100">
                  <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-400 to-blue-700 flex items-center justify-center text-2xl font-bold text-white shrink-0">
                    {selected.name.split(" ").map(n => n[0]).join("")}
                  </div>
                  <div>
                    <h2 className="font-syne font-extrabold text-slate-900 text-xl">{selected.name}</h2>
                    <p className="text-slate-500 text-sm">{selected.level} · {selected.university}</p>
                    <div className="flex gap-2 mt-2">
                      <span className={`badge ${STATUS_CFG[selected.status].badge}`}>{STATUS_CFG[selected.status].label}</span>
                      <span className="badge badge-blue">📍 {selected.wilaya}</span>
                    </div>
                  </div>
                </div>

                <div className="bg-blue-50 border border-blue-100 rounded-xl p-3 mb-5">
                  <div className="text-xs text-blue-500 font-semibold uppercase">Applied for</div>
                  <div className="text-sm font-semibold text-slate-800">{OFFERS.find(o => o.id === selected.offerId)?.title}</div>
                </div>

                <div className="mb-5">
                  <h4 className="text-xs font-semibold text-slate-400 uppercase mb-2">Skills</h4>
                  <div className="flex flex-wrap gap-1.5">
                    {selected.skills.map(s => <span key={s} className="skill-chip">{s}</span>)}
                  </div>
                </div>

                {selected.status === "pending" ? (
                  <button onClick={() => setModal(selected)} className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm">Review & decide →</button>
                  ) : (
                  <div className={`p-4 rounded-xl text-sm font-medium ${selected.status === "accepted" ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-red-50 text-red-700 border-red-200"} border`}>
                    Decision made: <strong>{STATUS_CFG[selected.status].label}</strong>
                  </div>
                )}
              </div>
            ) : (
              <div className="card border border-slate-200 p-10 text-center">
                <div className="text-4xl mb-3">👆</div>
                <p className="text-sm text-slate-400">Select a candidate to view their details.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {modal && (
        <DecisionModal
          candidate={modal}
          onClose={() => setModal(null)}
          onDecide={(id, status, note) => { handleDecide(id, status, note); setModal(null); }}
        />
      )}
    </CompanyLayout>
  );
}
